'use strict';

/**
 * Return an edit script of { op: 'equal' | 'delete' | 'insert', line: string }.
 * a and b are arrays of strings; lines are compared by exact string equality.
 * Reading equal/delete entries reconstructs a; equal/insert reconstructs b.
 * Equal entries must form a longest common subsequence: the number of deletes
 * plus inserts equals a.length + b.length - 2 * LCS(a, b).
 * Results must be deterministic. In every maximal region without an equal
 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b)) {
    throw new TypeError('diffLines expects two arrays of strings');
  }

  // Intern lines so the inner loops compare small integers.
  const ids = new Map();
  const intern = (line) => {
    let id = ids.get(line);
    if (id === undefined) {
      id = ids.size;
      ids.set(line, id);
    }
    return id;
  };
  const A = new Int32Array(a.length);
  const B = new Int32Array(b.length);
  for (let i = 0; i < a.length; i++) A[i] = intern(a[i]);
  for (let j = 0; j < b.length; j++) B[j] = intern(b[j]);

  // Raw ops: 0 = equal (a[i] === b[j]), 1 = delete a[i], 2 = insert b[j].
  const ops = [];
  diffRange(A, 0, A.length, B, 0, B.length, ops);

  // Emit, reordering each equal-free run so deletes precede inserts.
  const script = [];
  let i = 0;
  let j = 0;
  let k = 0;
  while (k < ops.length) {
    if (ops[k] === 0) {
      script.push({ op: 'equal', line: a[i] });
      i++;
      j++;
      k++;
      continue;
    }
    let dels = 0;
    let ins = 0;
    while (k < ops.length && ops[k] !== 0) {
      if (ops[k] === 1) dels++;
      else ins++;
      k++;
    }
    for (let n = 0; n < dels; n++) script.push({ op: 'delete', line: a[i++] });
    for (let n = 0; n < ins; n++) script.push({ op: 'insert', line: b[j++] });
  }
  return script;
}

/** Linear-space Myers diff of A[aLo, aHi) against B[bLo, bHi), appending raw ops. */
function diffRange(A, aLo, aHi, B, bLo, bHi, ops) {
  let prefix = 0;
  while (aLo < aHi && bLo < bHi && A[aLo] === B[bLo]) {
    aLo++;
    bLo++;
    prefix++;
  }
  let suffix = 0;
  while (aLo < aHi && bLo < bHi && A[aHi - 1] === B[bHi - 1]) {
    aHi--;
    bHi--;
    suffix++;
  }
  for (let n = 0; n < prefix; n++) ops.push(0);

  if (aLo === aHi) {
    for (let j = bLo; j < bHi; j++) ops.push(2);
  } else if (bLo === bHi) {
    for (let i = aLo; i < aHi; i++) ops.push(1);
  } else {
    const split = bisect(A, aLo, aHi, B, bLo, bHi);
    if (split === null) {
      for (let i = aLo; i < aHi; i++) ops.push(1);
      for (let j = bLo; j < bHi; j++) ops.push(2);
    } else {
      diffRange(A, aLo, split[0], B, bLo, split[1], ops);
      diffRange(A, split[0], aHi, B, split[1], bHi, ops);
    }
  }

  for (let n = 0; n < suffix; n++) ops.push(0);
}

/**
 * Find a point [x, y] (absolute indices) on a shortest edit path through the
 * middle of the edit graph, or null when the ranges share no line.
 * Forward V stores x reached on diagonal k = x - y; reverse V stores the
 * distance travelled back from the end on diagonal k = (N - x) - (M - y).
 */
function bisect(A, aLo, aHi, B, bLo, bHi) {
  const n = aHi - aLo;
  const m = bHi - bLo;
  const maxD = Math.ceil((n + m) / 2);
  const offset = maxD;
  const size = 2 * maxD + 2;
  const vf = new Int32Array(size).fill(-1);
  const vr = new Int32Array(size).fill(-1);
  vf[offset + 1] = 0;
  vr[offset + 1] = 0;
  const delta = n - m;
  const front = (delta & 1) !== 0;
  let kfStart = 0;
  let kfEnd = 0;
  let krStart = 0;
  let krEnd = 0;

  for (let d = 0; d < maxD; d++) {
    for (let k = -d + kfStart; k <= d - kfEnd; k += 2) {
      const ko = offset + k;
      let x = (k === -d || (k !== d && vf[ko - 1] < vf[ko + 1]))
        ? vf[ko + 1]
        : vf[ko - 1] + 1;
      let y = x - k;
      while (x < n && y < m && A[aLo + x] === B[bLo + y]) {
        x++;
        y++;
      }
      vf[ko] = x;
      if (x > n) {
        kfEnd += 2;
      } else if (y > m) {
        kfStart += 2;
      } else if (front) {
        const ro = offset + delta - k;
        if (ro >= 0 && ro < size && vr[ro] !== -1 && x >= n - vr[ro]) {
          return [aLo + x, bLo + y];
        }
      }
    }

    for (let k = -d + krStart; k <= d - krEnd; k += 2) {
      const ko = offset + k;
      let x = (k === -d || (k !== d && vr[ko - 1] < vr[ko + 1]))
        ? vr[ko + 1]
        : vr[ko - 1] + 1;
      let y = x - k;
      while (x < n && y < m && A[aHi - 1 - x] === B[bHi - 1 - y]) {
        x++;
        y++;
      }
      vr[ko] = x;
      if (x > n) {
        krEnd += 2;
      } else if (y > m) {
        krStart += 2;
      } else if (!front) {
        const fo = offset + delta - k;
        if (fo >= 0 && fo < size && vf[fo] !== -1) {
          const fx = vf[fo];
          const fy = fx - (fo - offset);
          if (fx >= n - x) return [aLo + fx, bLo + fy];
        }
      }
    }
  }
  return null;
}

/**
 * Return unified hunks: [{ oldStart, oldLines, newStart, newLines, lines }].
 * context is a nonnegative integer, default 3. Hunk lines are original strings
 * prefixed with ' ' (equal), '-' (delete), or '+' (insert); remove exactly one
 * prefix to recover a line, even when the original starts with a prefix itself.
 * oldLines counts context + deletes; newLines counts context + inserts.
 * Include up to context unchanged lines before/after each changed region.
 * Merge regions if the intervening unchanged gap is <= 2 * context (their
 * context would touch or overlap). Do not duplicate context in merged hunks.
 * Starts are 1-based, except a zero-line range names the line BEFORE the range:
 * oldLines === 0 uses the preceding old line number (0 for insertion at top),
 * and newLines === 0 uses the preceding new line number (0 for deletion at top).
 * Coordinates refer to the complete original a and result b, not a local hunk.
 * Identical inputs return []. Use diffLines' minimality and deletion ordering.
 * Neither input may be mutated. Inputs follow the diffLines contract.
 */
function unifiedHunks(a, b, { context = 3 } = {}) {
  if (!Number.isInteger(context) || context < 0) {
    throw new RangeError('context must be a nonnegative integer');
  }
  const script = diffLines(a, b);

  // Maximal changed regions as [start, end) script indices.
  const regions = [];
  for (let k = 0; k < script.length;) {
    if (script[k].op === 'equal') {
      k++;
      continue;
    }
    const start = k;
    while (k < script.length && script[k].op !== 'equal') k++;
    regions.push([start, k]);
  }

  const hunks = [];
  let oldPos = 0; // old lines consumed before script index `cursor`
  let newPos = 0;
  let cursor = 0;
  const advance = (to) => {
    for (; cursor < to; cursor++) {
      const op = script[cursor].op;
      if (op !== 'insert') oldPos++;
      if (op !== 'delete') newPos++;
    }
  };

  for (let r = 0; r < regions.length;) {
    let last = r;
    while (last + 1 < regions.length && regions[last + 1][0] - regions[last][1] <= 2 * context) {
      last++;
    }
    const from = Math.max(0, regions[r][0] - context);
    const to = Math.min(script.length, regions[last][1] + context);

    advance(from);
    const oldBefore = oldPos;
    const newBefore = newPos;
    const lines = [];
    let oldLines = 0;
    let newLines = 0;
    for (let k = from; k < to; k++) {
      const { op, line } = script[k];
      if (op === 'equal') {
        lines.push(' ' + line);
        oldLines++;
        newLines++;
      } else if (op === 'delete') {
        lines.push('-' + line);
        oldLines++;
      } else {
        lines.push('+' + line);
        newLines++;
      }
    }
    hunks.push({
      oldStart: oldLines === 0 ? oldBefore : oldBefore + 1,
      oldLines,
      newStart: newLines === 0 ? newBefore : newBefore + 1,
      newLines,
      lines,
    });
    r = last + 1;
  }
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  if (!Array.isArray(a) || !Array.isArray(hunks)) {
    throw new TypeError('applyHunks expects an array of lines and an array of hunks');
  }
  const isCount = (v) => Number.isInteger(v) && v >= 0;
  const result = [];
  let cursor = 0; // next unconsumed index in a
  let delta = 0; // new length minus old length from earlier hunks

  for (let h = 0; h < hunks.length; h++) {
    const fail = (why) => new Error(`hunk ${h} does not apply: ${why}`);
    const hunk = hunks[h];
    if (hunk === null || typeof hunk !== 'object') throw fail('not an object');
    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
    if (!isCount(oldStart) || !isCount(oldLines) || !isCount(newStart) || !isCount(newLines)) {
      throw fail('starts and counts must be nonnegative integers');
    }
    if (!Array.isArray(lines) || lines.length === 0) throw fail('lines must be a nonempty array');

    let olds = 0;
    let news = 0;
    for (const line of lines) {
      if (typeof line !== 'string' || line.length === 0) throw fail('invalid line');
      const prefix = line[0];
      if (prefix === ' ') {
        olds++;
        news++;
      } else if (prefix === '-') {
        olds++;
      } else if (prefix === '+') {
        news++;
      } else {
        throw fail(`invalid line prefix ${JSON.stringify(prefix)}`);
      }
    }
    if (olds !== oldLines || news !== newLines) throw fail('counts disagree with lines');

    if (oldLines > 0 && oldStart === 0) throw fail('oldStart must be 1-based');
    const pos = oldLines === 0 ? oldStart : oldStart - 1;
    if (pos < cursor) throw fail('overlaps or precedes an earlier hunk');
    if (pos + oldLines > a.length) throw fail('extends past the end of the input');
    const newPos = pos + delta;
    if (newStart !== (newLines === 0 ? newPos : newPos + 1)) throw fail('newStart disagrees with offset');

    const out = [];
    let i = pos;
    for (const line of lines) {
      const prefix = line[0];
      const text = line.slice(1);
      if (prefix === '+') {
        out.push(text);
        continue;
      }
      if (a[i] !== text) throw fail(`line ${i + 1} does not match`);
      if (prefix === ' ') out.push(text);
      i++;
    }

    for (; cursor < pos; cursor++) result.push(a[cursor]);
    for (const line of out) result.push(line);
    cursor = i;
    delta += newLines - oldLines;
  }

  for (; cursor < a.length; cursor++) result.push(a[cursor]);
  return result;
}

module.exports = { diffLines, unifiedHunks, applyHunks };

'use strict';
const assert = require('node:assert/strict');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) {
    dp[i][j] = a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
  }
  return dp[a.length][b.length];
}
let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
const alpha = ['', 'x', ' x', '-x', '+x', 'y', 'z'];
for (let t = 0; t < 20000; t++) {
  const a = Array.from({ length: rnd(14) }, () => alpha[rnd(1 + rnd(alpha.length))]);
  const b = Array.from({ length: rnd(14) }, () => alpha[rnd(1 + rnd(alpha.length))]);
  const ac = a.slice(), bc = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  const D = s.filter((e) => e.op !== 'equal').length;
  assert.equal(D, a.length + b.length - 2 * lcs(a, b), JSON.stringify([a, b]));
  for (let k = 1; k < s.length; k++) assert.ok(!(s[k - 1].op === 'insert' && s[k].op === 'delete'));
  assert.deepEqual(diffLines(a, b), s);
  for (const context of [0, 1, 2, 3]) {
    const h = unifiedHunks(a, b, { context });
    if (D === 0) assert.deepEqual(h, []);
    assert.deepEqual(applyHunks(a, h), b);
    for (let k = 1; k < h.length; k++) {
      const prevEnd = h[k - 1].oldStart - (h[k - 1].oldLines ? 1 : 0) + h[k - 1].oldLines;
      const start = h[k].oldStart - (h[k].oldLines ? 1 : 0);
      assert.ok(start - prevEnd > 2 * context);
    }
  }
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
}
