assert.throws(() => applyHunks(['a', 'b', 'c', 'd', 'e', 'f'], [h2[1], h2[0]]), /hunk 1 does not apply/);

// perf
const big = Array.from({ length: 20000 }, (_, i) => `line ${i % 50}`);
const big2 = big.slice(); big2.splice(10000, 3, 'X', 'Y'); big2[5] = 'q'; big2.push('end');
let t0 = process.hrtime.bigint();
const hb = unifiedHunks(big, big2);
assert.deepEqual(applyHunks(big, hb), big2);
console.log('small change ms', Number(process.hrtime.bigint() - t0) / 1e6);
const rep = Array.from({ length: 20000 }, () => 'same');
const rep2 = rep.slice(); rep2.splice(7000, 2); rep2.splice(15000, 0, 'other');
t0 = process.hrtime.bigint();
assert.equal(diffLines(rep, rep2).filter((e) => e.op !== 'equal').length, 3);
console.log('repetitive ms', Number(process.hrtime.bigint() - t0) / 1e6);
t0 = process.hrtime.bigint();
diffLines(big, big);
console.log('identical ms', Number(process.hrtime.bigint() - t0) / 1e6);
console.log('ok');

